    void Box(Graphics g,Rectangle r,Color fill,int radius){using(var path=Theme.Round(r,radius))using(var b=new SolidBrush(fill))g.FillPath(b,path);}
    void Button(Graphics g,string key,string text,Rectangle r,Action action,bool selected,bool enabled=true){double value;hover.TryGetValue(key,out value);value=FrameClock.Approach(value,enabled&&r.Contains(Point.Round(pointer))?1:0,dt);hover[key]=value;Color fill=selected?Color.FromArgb(74,30,37):Color.FromArgb(38,38,38);Box(g,r,Theme.Mix(fill,Color.FromArgb(85,48,52),value),9);using(var path=Theme.Round(r,9))using(var p=new Pen(selected?Theme.Red:Theme.Border,selected?2:1))g.DrawPath(p,path);Caption(g,text,new Rectangle(r.X+10,r.Y,r.Width-20,r.Height),16,enabled?Color.White:Theme.Muted,true,false,true);actions.Add(new RaceCanvasAction{Key=key,Text=text,Bounds=r,Execute=action,Enabled=enabled});}
    void Caption(Graphics g,string text,Rectangle r,int size,Color color,bool bold=false,bool wrap=false,bool center=false){string key=size+"/"+bold;Font f;if(!fonts.TryGetValue(key,out f)){f=new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel);fonts.Add(key,f);}using(var brush=new SolidBrush(color))using(var format=new StringFormat{Trimming=StringTrimming.EllipsisCharacter,LineAlignment=StringAlignment.Center,Alignment=center?StringAlignment.Center:StringAlignment.Near,FormatFlags=wrap?0:StringFormatFlags.NoWrap})g.DrawString(text??"",f,brush,r,format);}
    public override void Cancel(){if(pitDriver>=0){pitDriver=-1;Invalidate();return;}if(mapOpen){CloseMap();return;}if(Closing||complete)return;Race.Paused=true;Persist();if(Returned!=null)Returned();}
    protected override void Dispose(bool disposing){if(disposing)foreach(var f in fonts.Values)f.Dispose();base.Dispose(disposing);}
}
public class PowerReplacementOverlay:GameOverlay {
    public event Action Replaced,Cancelled;
    protected override Size SheetSize {get{return new Size(760,355);}}
    public PowerReplacementOverlay(Career s,int seat,int kind,bool animated):base(animated){var car=Powertrain.Car(Engine.Team(s,s.Player),seat);double cost=Powertrain.ReplacementPrice(car,kind);LabelAt(Sheet,"ЗАМЕНА / "+Powertrain.Names[kind],28,24,700,38,25,true,Color.White);LabelAt(Sheet,"Машина "+(seat+1)+" • ресурс "+car.Condition[kind].ToString("0.0")+"% → 100%\nНовый агрегат №"+(car.Used[kind]+1)+" / сезонный лимит "+Powertrain.Limits[kind]+"\n"+(cost>0?"Стоимость: "+Engine.Money(cost)+". Пилот стартует с конца решётки следующего Гран-при.":"В пределах сезонного лимита. Без оплаты и штрафа."),30,82,690,126,16);var error=LabelAt(Sheet,"",30,215,690,40,12,false,Theme.Red);var confirm=new SoftButton{Text="Установить",Primary=true,Bounds=new Rectangle(459,280,270,43)};var back=new SoftButton{Text="Назад",Bounds=new Rectangle(30,280,150,43)};Sheet.Controls.Add(confirm);Sheet.Controls.Add(back);confirm.Click+=(o,e)=>{try{Powertrain.Replace(s,seat,kind);if(Replaced!=null)Replaced();}catch(Exception ex){error.Text=ex.Message;}};back.Click+=(o,e)=>Cancel();}
    public override void Cancel(){if(!Closing&&Cancelled!=null)Cancelled();}
}
